   protected void doPost(HttpServletRequest clientRequest, HttpServletResponse response) throws ServletException, IOException {
       String encoding = clientRequest.getHeader("Accept-Encoding");
       boolean supportsGzip = (encoding != null && encoding.toLowerCase().indexOf("gzip") > -1);
       SessionTerminal st = (SessionTerminal) clientRequest.getSession(true).getAttribute("terminal");
       if (st == null || st.isClosed()) {
           st = new SessionTerminal(getCommandProcessor(), getThreadIO());
           clientRequest.getSession().setAttribute("terminal", st);
       }
       String str = clientRequest.getParameter("k");
       String f = clientRequest.getParameter("f");
       String dump = st.handle(str, f != null && f.length() > 0);
       if (dump != null) {
           if (supportsGzip) {
               response.setHeader("Content-Encoding", "gzip");
               response.setHeader("Content-Type", "text/html");
               try {
                   GZIPOutputStream gzos = new GZIPOutputStream(response.getOutputStream());
                   gzos.write(dump.getBytes());
                   gzos.close();
               } catch (IOException ie) {
                   LOG.info("Exception writing response: ", ie);
               }
           } else {
               response.getOutputStream().write(dump.getBytes());
           }
       }
   }

