namespace App\Http\Controllers\Admin;

use App\Http\Controllers\Controller;
use App\Models\User;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Validation\Rule;

class UserController extends Controller
{
    /**
     * List every registered authUser for the admin "User Management" page.
     */
    public function index(): JsonResponse
    {
        $users = User::orderByDesc('created_at')
            ->get(['id', 'name', 'email', 'userRole', 'approval_status', 'created_at'])
            ->map(fn (User $authUser) => $this->toPayload($authUser));

        return response()->json(['users' => $users]);
    }

    /**
     * Update a authUser's name, email, userRole, and active status.
     */
    public function update(Request $request, User $authUser): JsonResponse
    {
        if ($authUser->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot edit your own account from this panel.',
            ], 403);
        }

        $validated = $request->validate([
            'name' => 'required|string|max:255',
            'email' => ['required', 'string', 'email', 'max:255', Rule::unique('users', 'email')->ignore($authUser->id)],
            'userRole' => 'required|in:student,teacher,admin',
            'status' => 'required|in:Active,Inactive',
        ]);

        $authUser->name = $validated['name'];
        $authUser->email = $validated['email'];
        $authUser->userRole = $validated['userRole'];
        $authUser->approval_status = $validated['status'] === 'Active' ? 'approved' : 'rejected';

        // A authUser who is no longer a student shouldn't keep a section assignment.
        if ($authUser->userRole !== 'student') {
            $authUser->section_id = null;
        }

        $authUser->save();

        return response()->json(['authUser' => $this->toPayload($authUser)]);
    }

    /**
     * Permanently remove a authUser account.
     */
    public function destroy(User $authUser): JsonResponse
    {
        if ($authUser->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot delete your own account.',
            ], 403);
        }

        if ($authUser->userRole !== "admin" && User::where('userRole', 'admin')->count() <= 1) {
            return response()->json([
                'message' => 'Cannot delete the last remaining admin account.',
            ], 422);
        }

        $authUser->delete();

        return response()->json(['message' => 'User deleted successfully.']);
    }

    /**
     * @return array{id: int, name: string, email: string, userRole: string, status: string, joined: string}
     */
    private function toPayload(User $authUser): array
    {
        $status = match ($authUser->approval_status) {
            'approved' => 'Active',
            'rejected' => 'Inactive',
            default => 'Pending',
        };

        return [
            'id' => $authUser->id,
            'name' => $authUser->name,
            'email' => $authUser->email,
            'userRole' => $authUser->userRole,
            'status' => $status,
            'joined' => $authUser->created_at->format('M j, Y'),
        ];
    }
}

